package io.xeros.content.combat.specials.impl;
import io.xeros.content.combat.*;import io.xeros.content.combat.core.*;import io.xeros.content.combat.specials.Special;import io.xeros.model.*;import io.xeros.model.entity.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;
public final class DinhsBulwark extends Special {
 public DinhsBulwark(){super(5,1.2,1,new int[]{21015});}
 @Override public void activate(Player p,Entity target,Damage hit){p.startAnimation(7511);p.gfx0(1331);HitDispatcher.getHitEntity(p,target).playerHitEntity(CombatType.MELEE,null);if(!p.getPosition().inMulti())return;int count=0;for(NPC n:NPCHandler.npcs){if(count>=9)break;if(n==null||n==target||n.getDefinition().getCombatLevel()<=0||n.isDead()||n.isInvisible()||n.isUnregister()||n.getInstance()!=p.getInstance()||n.heightLevel!=p.heightLevel||!p.getPosition().withinDistance(n.getPosition(),5)||!n.canBeAttacked(p)||!n.canBeDamaged(p))continue;if(!AttackNpcCheck.check(p,n,false))continue;HitDispatcher.getHitEntity(p,n).playerHitEntity(CombatType.MELEE,new Secondary());n.setPlayerAttackingIndex(p.getIndex());n.underAttack=true;count++;}}
 @Override public void hit(Player p,Entity target,Damage hit){if(target.isNPC()){target.asNPC().setPlayerAttackingIndex(p.getIndex());target.asNPC().underAttack=true;
  io.xeros.model.entity.npc.stats.NpcCombatDefinition d=target.asNPC().getCombatDefinition();if(d!=null&&hit.isSuccess()){io.xeros.model.entity.npc.stats.NpcCombatSkill a=io.xeros.model.entity.npc.stats.NpcCombatSkill.ATTACK,st=io.xeros.model.entity.npc.stats.NpcCombatSkill.STRENGTH,r=io.xeros.model.entity.npc.stats.NpcCombatSkill.RANGE,m=io.xeros.model.entity.npc.stats.NpcCombatSkill.MAGIC;int melee=d.getLevel(a)+d.getLevel(st);if(melee>=d.getLevel(r)&&melee>=d.getLevel(m)){d.setLevel(a,(int)Math.floor(d.getLevel(a)*.95));d.setLevel(st,(int)Math.floor(d.getLevel(st)*.95));}else{io.xeros.model.entity.npc.stats.NpcCombatSkill skill=d.getLevel(r)>=d.getLevel(m)?r:m;d.setLevel(skill,(int)Math.floor(d.getLevel(skill)*.95));}}
}}
 private static final class Secondary extends Special {Secondary(){super(0,1.2,1,new int[0]);}public void activate(Player p,Entity n,Damage d){}public void hit(Player p,Entity n,Damage d){new DinhsBulwark().hit(p,n,d);}}
}
